(function () {
  var PORT = __PORT__;
  var panel = new URLSearchParams(location.search).get('panel') || 'dock';
  var base = 'http://127.0.0.1:' + PORT;
  function post(path, value) {
    try { fetch(base + path, { method: 'POST', body: JSON.stringify(value) }); } catch (e) {}
  }
  function wrapBridge(bridge) {
    var deliver = bridge.deliver;
    bridge.deliver = function (envelope) {
      var p = envelope.payload || {};
      var entry = { t: Date.now(), panel: panel, type: envelope.type };
      if (envelope.type === 'state') entry.payload = { session: p.session && p.session.kind, agent: p.agent, chatModel: p.chatModel,
        active: p.activeConversationId };
      else if (envelope.type === 'assistant_delta') entry.payload = { text: p.text };
      else entry.payload = p;
      post('/log', entry);
      return deliver.apply(this, arguments);
    };
    post('/log', { t: Date.now(), panel: panel, type: 'instrumented' });
  }
  // Hooked as the page creates the bridge, so the handshake is seen too.
  var real;
  Object.defineProperty(window, '__jusprinBridge', {
    configurable: true,
    get: function () { return real; },
    set: function (value) { real = value; if (value && value.deliver) wrapBridge(value); },
  });
  var seq = 0;
  setInterval(function () {
    fetch(base + '/cmd?panel=' + panel).then(function (r) { return r.json(); }).then(function (items) {
      items.forEach(function (item) {
        if (item.type === '__dump') {
          post('/log', { t: Date.now(), panel: panel, type: 'dump', payload: { text: document.body.innerText } });
          return;
        }
        var envelope = { protocol: 'jusprin-agent-bridge', version: 1, id: 'e2e-' + (++seq), type: item.type, payload: item.payload || {} };
        post('/log', { t: Date.now(), panel: panel, type: 'sent:' + item.type, payload: item.payload || {} });
        window.wx.postMessage(JSON.stringify(envelope));
      });
    }).catch(function () {});
  }, 300);
})();
"""Serves the instrumented Agent page, records what the host sends it, and
hands each page the messages queued for it."""
import json, sys, threading
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

queues, lock = {}, threading.Lock()
log = open('log.jsonl', 'a', buffering=1)

class Handler(SimpleHTTPRequestHandler):
    def log_message(self, *args): pass
    def _json(self, value):
        body = json.dumps(value).encode()
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Access-Control-Allow-Origin', '*')
        self.end_headers()
        self.wfile.write(body)
    def do_GET(self):
        url = urlparse(self.path)
        q = parse_qs(url.query)
        if url.path == '/cmd':
            panel = q.get('panel', [''])[0]
            with lock:
                items = queues.pop(panel, [])
            return self._json(items)
        return super().do_GET()
    def end_headers(self):
        # The app's web views must load this run's page, never a cached one.
        self.send_header('Cache-Control', 'no-store')
        super().end_headers()
    def do_POST(self):
        url = urlparse(self.path)
        q = parse_qs(url.query)
        body = self.rfile.read(int(self.headers.get('Content-Length', 0)) or 0)
        if url.path == '/log':
            log.write(body.decode() + '\n')
            return self._json({})
        if url.path == '/queue':
            panel = q.get('panel', [''])[0]
            with lock:
                queues.setdefault(panel, []).extend(json.loads(body))
            return self._json({})
        self.send_response(404); self.end_headers()
    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Headers', '*')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST')
        self.end_headers()

ThreadingHTTPServer(('127.0.0.1', int(sys.argv[1])), Handler).serve_forever()

