import json,time,os,sys
LOG='/private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin/2fa7e918-fcbc-44a3-a184-63d038ab7668/scratchpad/page/log.jsonl'
ACT=('assistant_started','assistant_delta','assistant_completed','tool_activity','work_updated','message_added','conversations_updated')
def wait(start, limit=900, quiet=15):
    t0=time.time(); busy=None; opened=set(); ended=set(); last_act=time.time(); work_open=False
    while time.time()-t0<limit:
        time.sleep(2)
        opened=set(); ended=set()
        with open(LOG) as f:
            f.seek(start); lines=f.readlines()
        for l in lines:
            try: d=json.loads(l)
            except: continue
            if d['type'] in ACT: last_act=d['t']/1000
            if d['type']=='conversations_updated':
                p=d.get('payload'); busy = ('"busy":true' in p) if isinstance(p,str) else p.get('busy')
            if d['type']=='work_updated':
