        m=re.match(r'; (total filament weight \[g\]|filament used \[g\]|total estimated time|model printing time|total layer number|support_type|enable_support|sparse_infill_density|wall_loops|support_threshold_angle|sparse_infill_pattern|top_shell_layers|bottom_shell_layers) *[:=] *(.*)',line)
        if m: meta[m.group(1)]=m.group(2).strip()
