    if line.startswith('M83'): rel=True
    elif line.startswith('M82'): rel=False
    elif line.startswith('G92'):
        m=re.search(r'E(-?[\d.]+)',line)
        if m: lastE=float(m.group(1))
    if line.startswith(('G1','G0')):
        mz=re.search(r' Z([\d.]+)',line)
        if mz: z=float(mz.group(1))
