                if 'upport' in role: b=int(z//5)*5; supz[b]=supz.get(b,0)+d
tot=sum(e_by.values()); w=sum(float(x) for x in meta.get('filament used [g]','0').split(','))
print('file',f, 'mtime', os.path.getmtime(f))
print('meta', meta)

